export function splitIntNumberStrToArray(value, separator = ',', maxLen, name = '', vueInstance) {
  const reg = /\D/
  let list = []
  if (value) {
    list = value
      .split(separator)
      .map((s) => s.trim())
      .filter((s) => s)
    const existNaN = list.some((v) => reg.test(v))
    if (existNaN) {
      return false
    }
    if (vueInstance && isNum(maxLen) && maxLen > 0 && list.length > maxLen) {
      vueInstance.$message({
        type: 'warning',
        message: name + '不能超过' + maxLen + '个'
      })
      return false
    }
  }
  return list
}

