output [31:0] pc,
output [31:0] aluout,
output [31:0] mem_writedata,
output [31:0] mem_addr,
output wire memena,
output wire zero,
output wire overflow
);
wire [4:0] reg_writeaddr;
wire [31:0] reg_writedata;

wire [31:0] reg_data_1;
wire [31:0] reg_data_2;

wire [31:0] alu_ina;
wire [31:0] alu_inb;

wire [31:0] pc_temp; // IF branch
wire [31:0] pc_in_temp; //IF jump
wire [31:0] pc_in;

assign alu_ina = reg_data_1;

assign mem_addr = aluout;
assign mem_writedata = reg_data_2;

regfile regm(
.clk(clk),
.we3(regwrite),
.ra1(instr[25:21]),
.ra2(instr[20:16]),
.wa3(reg_writeaddr),
.wd3(reg_writedata),
.rd1(reg_data_1),
.rd2(reg_data_2)
);

// select destination register rs1 or rs2 (regdst)
mux2x1 #(5) mux1(
.sel(regdst),
.d1(instr[15:11]),
.d0(instr[20:16]),
.y(reg_writeaddr)
);

alu alc(
.op(alucontrol),
.num1(alu_ina),
.num2(alu_inb),
.result(aluout),
.overflow(overflow),
.zero(zero)
);

// select where the reg data to be writen from alu or data_mem (memtoreg) addi,lw
mux2x1 mux2(
.sel(memtoreg),
.d0(aluout),
.d1(readdata),
.y(reg_writedata)
);

// select regdata_2 or immidiate data in the instr (alusrc)
mux2x1 mux3(
.sel(alusrc),
.d0(reg_data_2),
.d1( {{16{instr[15]}},{instr[15:0]}} ),
.y(alu_inb)
);

pc_reg pcreg(
.clk(clk),
.rst(rst),
.pc_in(pc_in),
.pc_out(pc),
.ena(memena)
);

assign pc_temp = pc + 4;

// select pc+4 or pc+4 + instr[‘addr’] (branch)
mux2x1 mux4(
.sel(pcsrc),
.d0(pc_temp),
.d1( {{pc_temp}} + ( {{16{instr[15]}},{instr[15:0]}} << 2)),
.y(pc_in_temp)
);

// select pc+4 or pc+4[31:28]:instr[addr] (jump)
mux2x1 mux5(
.sel(jump),
.d0(pc_in_temp),
.d1( { {pc_in_temp[31:28]}, {instr[25:0]}, 2’b00} ),
.y(pc_in)
);
endmodule
