                        imageView.setImageBitmap(scaledDownBitmap)
                    }
                })
        }
    }




    private fun upscaleImage(bitmap: Bitmap, scale: Double): Bitmap {
        val inputMat = Mat()
        val outputMat = Mat()

        Utils.bitmapToMat(bitmap, inputMat)

        // Apply enhancement to the image
        val enhancedMat = Mat()
        Imgproc.cvtColor(inputMat, enhancedMat, Imgproc.COLOR_BGR2GRAY)
        Imgproc.equalizeHist(enhancedMat, enhancedMat)

        // Upscale the enhanced image
        Imgproc.pyrUp(enhancedMat, outputMat, Size(inputMat.width() * scale, inputMat.height() * scale))

        // Create a new Bitmap with the scaled dimensions
        val scaledBitmap = Bitmap.createScaledBitmap(bitmap, (bitmap.width * scale).toInt(), (bitmap.height * scale).toInt(), false)

        // Get the scaled bitmap using the outputMat
        val outputBitmap = Bitmap.createBitmap(scaledBitmap.width, scaledBitmap.height, Bitmap.Config.ARGB_8888)
        Utils.matToBitmap(outputMat, outputBitmap)

        // Recycle the input bitmap to free up memory
        bitmap.recycle()
        scaledBitmap.recycle()

        return outputBitmap
    }



