Widget _buildLauncherButton(
    IconData iconData,
    VoidCallback? onPressedCallback,
    String key,
    BuildContext context,
  ) {
    final l10n = AppLocalizations.of(context)!;

    return PatientAppIconButton(
      iconData: iconData,
      onPressed: () async {
        String? permissionKey;
        switch (key) {
          case SettingsRepository.phoneAppLaunchPermission:
            permissionKey = SettingsRepository.phoneAppLaunchPermission;
            break;
          case SettingsRepository.mailAppLaunchPermission:
            permissionKey = SettingsRepository.mailAppLaunchPermission;
            break;
          case SettingsRepository.mapAppLaunchPermission:
            permissionKey = SettingsRepository.mapAppLaunchPermission;
            break;
        }

        final permission = await LaunchPermissionProvider()
            .readLaunchPermission(permissionKey!);

        if (permission == null || permission == false) {
          String title = '';
          String description = '';
          switch (key) {
            case SettingsRepository.phoneAppLaunchPermission:
              title =
                  l10n.general_launchPermissionTitle(l10n.general_phoneLabel);
              description = l10n
                  .general_launchPermissionDescription(l10n.general_phoneLabel);
              break;
            case SettingsRepository.mailAppLaunchPermission:
              title =
                  l10n.general_launchPermissionTitle(l10n.general_mailLabel);
              description = l10n
                  .general_launchPermissionDescription(l10n.general_mailLabel);
              break;
            case SettingsRepository.mapAppLaunchPermission:
              title = l10n.general_launchPermissionTitle(l10n.general_mapLabel);
              description = l10n
                  .general_launchPermissionDescription(l10n.general_mapLabel);
              break;
          }

          showDialog(
            context: context,
            builder: (context) {
              return AlertDialog(
                title: Text(title),
                content: Text(description),
                actions: <Widget>[
                  TextButton(
                    style: theme.dialogSecondaryTextButtonStyle,
                    onPressed: () => Navigator.pop(context),
                    child: Text(l10n.general_cancelButtonLabel),
                  ),
                  TextButton(
                    style: theme.dialogPrimaryTextButtonStyle,
                    onPressed: () async {
                      Navigator.pop(context);
                      await LaunchPermissionProvider()
                          .storeLaunchPermission(permissionKey!, true);
                      if (onPressedCallback != null) {
                        onPressedCallback();
                      }
                    },
                    child: Text(l10n.general_confirmButtonLabel),
                  ),
                ],
              );
            },
          );
        }
      },
    );
  }
}

